function rpg_json(mixed $value):string { return json_encode($value,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR); }
function rpg_decode(mixed $value,array $default=[]):array { if(is_array($value))return $value; $v=json_decode((string)$value,true);return is_array($v)?$v:$default; }
function rpg_kind(string $kind):string { if($kind==='player')$kind='pg';if(!in_array($kind,['pg','npc'],true))throw new DomainException('Tipo di personaggio non valido.',422);return $kind; }
function rpg_int(mixed $value,int $min,int $max,string $label='Valore'):int { if(filter_var($value,FILTER_VALIDATE_INT)===false||$value<$min||$value>$max)throw new DomainException($label.' non valido.',422);return (int)$value; }
function rpg_text(mixed $value,int $max,bool $required=false):string { if(!is_string($value)||mb_strlen($value)>$max||($required&&trim($value)===''))throw new DomainException('Testo non valido.',422);return trim($value); }
function rpg_bool(mixed $value):bool { if(!in_array($value,[true,false,0,1,'0','1'],true))throw new DomainException('Opzione non valida.',422);return (bool)$value; }
function rpg_ready():bool { static $ready; if($ready===null)$ready=(bool)ConnectDB()->query("SHOW TABLES LIKE 'rpg_progress'");return $ready; }
/** Only the static catalogue is cached per request; player balances are always current reads. */
function rpg_catalog(bool $refresh=false):array {
 static $cache,$cachedAt=0;if($refresh||microtime(true)-$cachedAt>2)$cache=null;if($cache!==null)return $cache;$cachedAt=microtime(true);
 $db=ConnectDB();$stats=$db->query('SELECT stat_key AS `key`,name,description,icon,position FROM rpg_characteristics ORDER BY position,stat_key');
 $transformation=alphano_transformation_ready()?',c.human_default,c.transformation_enabled,c.transformation_human_text,c.transformation_special_text,c.transformation_stats':'';
 $language=alphano_race_language_ready()?',c.loses_human_language':'';
 $races=$db->query('SELECT r.id,r.nome AS name,r.forza,c.base_stats,c.description,c.source,c.special,c.enabled'.$transformation.$language.' FROM razze r LEFT JOIN rpg_races c ON c.race_id=r.id ORDER BY r.id');
 foreach($races as &$r){$r['id']=(int)$r['id'];$r['stats']=array_replace(array_fill_keys(RPG_STATS,10),rpg_decode($r['base_stats']));$r['stats']['strength']=max(0,min(100,(int)$r['forza']));$r['special']=(bool)$r['special'];$r['enabled']=$r['enabled']===null?true:(bool)$r['enabled'];$defaults=alphano_transformation_default_messages($r['id']);$r['human_default']=(bool)($r['human_default']??(false));$r['loses_human_language']=(bool)($r['loses_human_language']??(false));$r['transformation_enabled']=(bool)($r['transformation_enabled']??false);$r['transformation_human_text']=(string)($r['transformation_human_text']??$defaults['human']);$r['transformation_special_text']=(string)($r['transformation_special_text']??$defaults['special']);unset($r['base_stats']);}unset($r);
 $orgPublications=rpg_org_publications();$abilities=$db->query('SELECT * FROM rpg_abilities ORDER BY category,id');foreach($abilities as &$a){$a['id']=(int)$a['id'];if(isset($orgPublications[$a['id']]))$a['organization']=$orgPublications[$a['id']];$a['key']=$a['ability_key'];unset($a['ability_key']);foreach(['race_ids','requirements','effect'] as $key)$a[$key]=rpg_decode($a[$key]);$a['innate']=$a['category']!=='purchasable';$a['cost']=(int)$a['cost'];$a['learnable']=rpg_ability_learnable($a);if($a['learnable']&&$a['category']==='innate'&&$a['cost']<1)$a['cost']=(int)rpg_human_manual()['learning_cost'];$a['cooldown']=(int)$a['cooldown'];$a['enabled']=(bool)$a['enabled'];if($rule=rpg_human_rule($a['key']))$a['rules']=array_replace($rule,$a['effect']['manual_rules']??[]);}unset($a);
 return $cache=['stats'=>$stats,'races'=>$races,'abilities'=>$abilities,'lineage_policy'=>rpg_lineage_policy()];
}
