 $out=[];foreach($labels as $key=>$name)$out[]=['key'=>$key,'name'=>$name,'min'=>str_contains($key,'min_')?1:0,'max'=>$key==='quest_xp_enabled'?1:(str_starts_with($key,'quest_')?1000:300),'description'=>str_starts_with($key,'quest_')?'Ricompense registrate una sola volta dal motore.':'Coefficiente in centesimi: 100 equivale a 1,00.'];
