  'defence_bonus'=>['Bonus della dichiarazione difensiva',0,50],
  'held_penalty'=>['Penalità per una presa subita',0,100],
  'wound_penalty_max'=>['Penalità massima delle ferite',0,100],
  'damage_min'=>['Danno minimo di un colpo riuscito',0,1000],
  'damage_max'=>['Danno massimo di un colpo riuscito',1,1000],
  'unarmed_multiplier'=>['Moltiplicatore del danno a mani nude',0,10],
  'weapon_multiplier'=>['Moltiplicatore del danno con arma',0,10],
  'margin_multiplier'=>['Danno per margine di successo',0,10],
  'armor_absorption'=>['Assorbimento dell’armatura utilizzabile',0,500],
  'reward_min_rounds'=>[alphano_currency_text('Giri minimi per ricompensa in corone'),1,1000],
  'reward_min_actions'=>[alphano_currency_text('Azioni minime per ricompensa in corone'),1,1000],
  'reward_daily_cap'=>[alphano_currency_text('Massimo corone dalle quest in 24 ore'),0,1000],
  'reward_cooldown'=>[alphano_currency_text('Attesa tra ricompense in corone, secondi'),0,604800]
 ];
 foreach($scene as $key=>[$name,$min,$max])$out[]=['key'=>'scene_'.$key,'name'=>$name,'min'=>$min,'max'=>$max,'description'=>'Regola centralizzata della scena: '.$key.'. Le condizioni di mortalità e immortalità delle stirpi rimangono nel motore.'];
 return $out;
}
function rpg_settings(bool $refresh=false):array { static $cache,$cachedAt=0,$seed;if($refresh||microtime(true)-$cachedAt>2)$cache=null;if($cache!==null)return $cache;$seed??=json_decode(file_get_contents(__DIR__.'/../config/rpg-seed.json'),true)['settings'];$defaults=$seed;foreach(ConnectDB()->query('SELECT setting_key,value FROM rpg_settings') as $r)if(array_key_exists($r['setting_key'],$defaults))$defaults[$r['setting_key']]=(int)$r['value'];$cachedAt=microtime(true);return $cache=$defaults+['stat_cap'=>100,'initial_points'=>(int)alphano_config('initial_points'),'xp_per_stat'=>1]; }
/** Physical human shape does not remove a lycan from its lineage's public roster. */
function alphano_race_sql():string {return 'razza';}
function rpg_identity(string $kind,int $id,bool $lock=false):array {
 $kind=rpg_kind($kind);if($id<1)throw new DomainException('Personaggio non valido.',422);$db=ConnectDB();
 if($kind==='pg'){$vampire=alphano_transformation_ready()?'alternate_form':'0 AS alternate_form';$raw=$db->query('SELECT id,nome AS name,razza,senziente,infetto,ancestrale,puntif,ferite,bloccato,organizzazione,caricaorganizzazione,COALESCE((SELECT c.livello FROM caricheorganizzazioni c WHERE c.id=u.caricaorganizzazione AND c.organizzazione=u.organizzazione),0) AS organization_level,'.$vampire.' FROM utenti u WHERE id=?'.($lock?' FOR UPDATE':''),[$id])[0]??null;$r=$raw?['id'=>$raw['id'],'name'=>$raw['name'],'race_id'=>alphano_visible_race($raw),'native_race_id'=>alphano_native_race($raw),'organization_id'=>(int)$raw['organizzazione'],'organization_rank_id'=>(int)$raw['caricaorganizzazione'],'organization_rank_level'=>(int)$raw['organization_level'],'lineage_race_id'=>alphano_native_race($raw),'sentient'=>$raw['senziente'],'hit_points'=>$raw['puntif'],'wounds'=>$raw['ferite'],'transformation_form'=>!empty($raw['alternate_form'])?'native':'human']:null;}
 else{$raw=$db->query('SELECT id,name,profile,active FROM ai_npcs WHERE id=?'.($lock?' FOR UPDATE':''),[$id])[0]??null;if($raw){$p=rpg_decode($raw['profile']);$g=$db->query('SELECT settings FROM ai_npc_game WHERE npc_id=?',[$id])[0]??[];$r=['id'=>$id,'name'=>$raw['name'],'active'=>(bool)$raw['active'],'race_id'=>(int)($p['race_id']??1),'sentient'=>(int)(rpg_decode($g['settings']??'{}')['sentient']??0),'wounds'=>(string)($p['wounds']??''),'hit_points'=>(int)($p['hit_points']??1000)];if(isset($p['strength'])&&is_numeric($p['strength']))$r['strength_override']=max(0,min(100,(int)$p['strength']));}}
 if(empty($r))throw new DomainException('Personaggio non trovato.',404);$r['id']=(int)$r['id'];$r['kind']=$kind;$r['race_id']=(int)$r['race_id'];if($r['race_id']===ALPHANO_RACE_LEGACY_SPIRIT)$r['race_id']=ALPHANO_RACE_SPIRIT;$r['sentient']=$r['race_id']===6||!empty($r['sentient']);return $r;
}
function rpg_progress(string $kind,int $id,bool $lock=false):array {
 $kind=rpg_kind($kind);$db=ConnectDB();if($lock)$db->execute("INSERT IGNORE INTO rpg_progress(owner_kind,owner_id,initial_stats,trained_stats) VALUES(?,?,'{}','{}')",[$kind,$id]);
 $r=$db->query('SELECT * FROM rpg_progress WHERE owner_kind=? AND owner_id=?'.($lock?' FOR UPDATE':''),[$kind,$id])[0]??['owner_kind'=>$kind,'owner_id'=>$id,'xp_total'=>0,'xp_spent'=>0,'xp_stats'=>0,'xp_abilities'=>0,'initial_claimed'=>0,'initial_stats'=>'{}','trained_stats'=>'{}','version'=>0];foreach(['xp_total','xp_spent','xp_stats','xp_abilities','version'] as $key)$r[$key]=(int)$r[$key];return $r;
}
function rpg_atomic(callable $callback):mixed { $db=ConnectDB();$owned=!$db->inTransaction();if($owned)$db->beginTransaction();try{$result=$callback();if($owned)$db->commit();return $result;}catch(Throwable $e){if($owned&&$db->inTransaction())$db->rollBack();throw $e;} }
function rpg_race(int $race):array { if($race===0)return ['id'=>0,'name'=>'Non assegnata','stats'=>array_fill_keys(RPG_STATS,10),'special'=>false,'enabled'=>true,'human_default'=>false,'transformation_enabled'=>false,'description'=>'','source'=>''];foreach(rpg_catalog()['races'] as $r)if($r['id']===$race)return $r;throw new DomainException('Razza non configurata.',422); }
function rpg_stat_values(array $identity,array $p):array { $base=rpg_race($identity['race_id'])['stats'];if(($identity['transformation_form']??'human')==='native')$base=array_replace($base,alphano_transformation_config($identity['race_id'])['stats']);if(isset($identity['strength_override']))$base['strength']=$identity['strength_override'];$initial=rpg_decode($p['initial_stats']);$trained=rpg_decode($p['trained_stats']);$stats=[];foreach(RPG_STATS as $key)$stats[$key]=max(0,min(100,(int)$base[$key]+(int)($initial[$key]??0)+(int)($trained[$key]??0)));return $stats; }
/** Growth belongs to the character; alternate physical bases share the same investments. */
function rpg_stat_forms(array $identity,array $progress):array {
 $config=alphano_transformation_config((int)$identity['race_id']);$forms=[];
 foreach($config['enabled']?['human','native']:['human'] as $shape){$form=$identity;$form['transformation_form']=$shape;$forms[]=['race_id'=>(int)$identity['race_id'],'name'=>$shape==='human'?'Forma ordinaria':'Forma alternativa','stats'=>rpg_stat_values($form,$progress)];}return $forms;
}
function rpg_stat_training_room(array $forms,string $stat):int {return max(0,min(array_map(static fn($form)=>100-(int)$form['stats'][$stat],$forms)));}
function rpg_actor_stats(string $kind,int $id):array { $kind=rpg_kind($kind);return rpg_stat_values(rpg_identity($kind,$id),rpg_progress($kind,$id)); }
/** Acquisition uses native lineage, never a disguise or a previously learned foreign power. */
function rpg_ability_race_allowed(array $ability,int $race):bool {
 return rpg_ability_lineage_reason($ability,['race_id'=>$race,'native_race_id'=>$race])==='';
}
function rpg_ability_image(mixed $value):string {
 $value=rpg_text($value??'',512);if($value==='')return '';
 if(preg_match('~^/uploads/[A-Za-z0-9/_-]+\.(?:png|jpe?g|webp|gif)$~D',$value)&&!str_contains($value,'..'))return $value;
 if(filter_var($value,FILTER_VALIDATE_URL)&&str_starts_with($value,'https://')&&!parse_url($value,PHP_URL_USER)&&!parse_url($value,PHP_URL_PASS))return $value;
 throw new DomainException('Immagine non valida: usa un percorso immagini locale o un collegamento HTTPS.',422);
}
function rpg_requirements_reason(array $a,array $identity,array $stats,array $owned,bool $learning=false):string {
 if(!alphano_config('abilities_enabled'))return 'Sistema di abilità disabilitato dalla gestione.';
 if(!$a['enabled'])return 'Abilità disabilitata.';if(!rpg_race($identity['race_id'])['enabled'])return 'Progressione di questa razza sospesa.';
 $reason=$learning?rpg_ability_lineage_reason($a,$identity):rpg_ability_form_reason($a,$identity);if($reason!=='')return $reason;
 if(!rpg_race(rpg_lineage_id($identity))['enabled'])return 'Progressione della stirpe sospesa.';
 $organizationReason=rpg_org_membership_reason($a,$identity);if($organizationReason!=='')return $organizationReason;
 $r=$a['requirements'];foreach(($r['stats']??[]) as $key=>$value)if(($stats[$key]??0)<$value)return 'Richiede '.(rpg_stat_name($key)).' almeno '.$value.'.';
 if(isset($r['sentient'])&&$r['sentient']!==null&&(bool)$r['sentient']!==(bool)$identity['sentient'])return $r['sentient']?'Richiede la Senzienza registrata.':'Riservata alla forma Pura.';
 foreach(($r['abilities']??[]) as $id)if(!in_array((int)$id,$owned,true))return 'Richiede un’altra abilità non ancora appresa.';
 if($identity['kind']==='npc'&&empty($identity['active']))return 'Il PNG non è attivo.';if($identity['hit_points']<1&&!in_array($identity['race_id'],[4,7],true))return 'Il personaggio è fuori combattimento.';return '';
}
function rpg_stat_name(string $key):string { foreach(rpg_catalog()['stats'] as $s)if($s['key']===$key)return $s['name'];return $key; }
function rpg_abilities_for(string $kind,int $id,array $identity,array $stats,array $p):array {
 $learnedCosts=array_column(ConnectDB()->query('SELECT ability_id,cost FROM rpg_learned WHERE owner_kind=? AND owner_id=?',[$kind,$id]),'cost','ability_id');$learned=array_map('intval',array_keys($learnedCosts));$creation=rpg_creation_status($kind,$id,$identity);
 $native=rpg_lineage_id($identity);$innate=[];$catalog=rpg_catalog()['abilities'];
 foreach($catalog as $a)if($a['innate']&&!rpg_human_rule($a['key'])&&$a['enabled']&&rpg_ability_race_allowed($a,$native))$innate[]=$a['id'];
 $pendingHuman=$kind==='pg'&&$native===alphano_human_race_id()&&($creation['needs_points']||$creation['needs_innates']);
 if($pendingHuman){$learned=[];$innate=[];}
 $owned=array_unique([...$learned,...$innate]);$out=[];
 foreach($catalog as $a){
  if(isset($a['organization'])&&(int)($identity['organization_id']??0)!==$a['organization']['id']&&!in_array($a['id'],$learned,true))continue;
  if(!rpg_ability_race_allowed($a,$native)&&!in_array($a['id'],$learned,true))continue;
  $a['owned']=in_array($a['id'],$owned,true);$a['acquisition']=$a['owned']?(array_key_exists($a['id'],$learnedCosts)?((int)$learnedCosts[$a['id']]===0?'initial':'purchased'):'racial'):null;$a['access']=rpg_ability_access($a,$identity);
  $learning=$identity;$learning['race_id']=$a['access']['learning_race_id'];$learningStats=rpg_stat_values($learning,$p);
  $reason=rpg_requirements_reason($a,$identity,$a['owned']?$stats:$learningStats,$owned,!$a['owned']);
  $a['automatic']=false;$a['usable']=$a['owned']&&$reason==='';$a['available']=$reason===''&&($a['owned']||$p['xp_total']-$p['xp_spent']>=$a['cost']);
  $a['reason']=$reason!==''?$reason:(!$a['owned']&&!$a['available']?'Esperienza disponibile insufficiente.':'');
  if(isset($a['rules'])&&$a['category']==='innate'&&!$a['owned']&&$creation['needs_innates']){$a['available']=false;$a['reason']='Scegli prima le quattro innate gratuite nella creazione del personaggio.';}
  if(isset($a['rules'])&&$a['rules']['number']>=51&&$a['owned']&&$reason===''){$a['automatic']=true;$a['usable']=false;$a['reason']='Resistenza automatica ai comandi vampirici, senza azione aggiuntiva.';}
  if($pendingHuman){$a['available']=false;$a['usable']=false;$a['reason']='Completa prima le caratteristiche e le quattro innate gratuite.';}
  $a['use_reason']=rpg_ability_form_reason($a,$identity);$out[]=$a;
 }return $out;
}
function rpg_history(string $kind,int $id,int $before=0):array { $kind=rpg_kind($kind);$rows=ConnectDB()->query('SELECT id,entry_type AS type,amount,xp_total,xp_spent,reason,payload,actor_id,created_at FROM rpg_ledger WHERE owner_kind=? AND owner_id=?'.($before>0?' AND id<?':'').' ORDER BY id DESC LIMIT 31',$before>0?[$kind,$id,$before]:[$kind,$id]);$next=count($rows)>30?(int)$rows[29]['id']:null;$rows=array_slice($rows,0,30);foreach($rows as &$r){foreach(['id','amount','xp_total','xp_spent','actor_id','created_at'] as $k)$r[$k]=(int)$r[$k];$r['payload']=rpg_decode($r['payload']);}return ['items'=>$rows,'next'=>$next]; }
/** Shared read-only projection for the HTML header and the interactive RPG API. */
function rpg_characteristics(array $identity,array $progress):array {
 $base=rpg_race($identity['race_id'])['stats'];if(($identity['transformation_form']??'human')==='native')$base=array_replace($base,alphano_transformation_config($identity['race_id'])['stats']);if(isset($identity['strength_override']))$base['strength']=$identity['strength_override'];
 $initial=rpg_decode($progress['initial_stats']);$trained=rpg_decode($progress['trained_stats']);$values=rpg_stat_values($identity,$progress);$forms=rpg_stat_forms($identity,$progress);$out=[];
 foreach(rpg_catalog()['stats'] as $s)$out[]=$s+['base'=>(int)$base[$s['key']],'initial'=>(int)($initial[$s['key']]??0),'trained'=>(int)($trained[$s['key']]??0),'value'=>$values[$s['key']],'max'=>100,'training_room'=>rpg_stat_training_room($forms,$s['key']),'forms'=>array_map(static fn($f)=>['race_id'=>$f['race_id'],'name'=>$f['name'],'value'=>$f['stats'][$s['key']]],$forms)];
 return $out;
}
function rpg_sheet(string $kind,int $id,bool $history=true):array {
 $kind=rpg_kind($kind);$identity=rpg_identity($kind,$id);$p=rpg_progress($kind,$id);$race=rpg_race($identity['race_id']);$initial=rpg_decode($p['initial_stats']);$stats=rpg_stat_values($identity,$p);$characteristics=rpg_characteristics($identity,$p);
 $identity['race']=$race['name'];$identity['race_name']=$race['name'];$identity['special']=$race['special'];$identity['race_enabled']=$race['enabled'];return ['identity'=>$identity,'lineage'=>rpg_lineage_sheet($identity),'characteristics'=>$characteristics,'stats'=>$stats,'xp'=>['total'=>$p['xp_total'],'spent'=>$p['xp_spent'],'available'=>$p['xp_total']-$p['xp_spent'],'spent_stats'=>$p['xp_stats'],'spent_abilities'=>$p['xp_abilities']],'creation'=>rpg_creation_status($kind,$id,$identity),'malus'=>rpg_racial_sheet($kind,$id,$identity),'initial'=>['points'=>(int)alphano_config('initial_points'),'claimed'=>rpg_creation_status($kind,$id,$identity)['manual_points'],'allocation'=>$initial],'abilities'=>rpg_abilities_for($kind,$id,$identity,$stats,$p),'history'=>$history?rpg_history($kind,$id):['items'=>[],'next'=>null],'version'=>$p['version']];
}
function rpg_request_key(mixed $key):string { if(!is_string($key)||!preg_match('/^[a-zA-Z0-9:_.-]{8,140}$/D',$key))throw new DomainException('Identificativo della richiesta non valido.',422);return $key; }
function rpg_event_key(mixed $key):string { if(!is_string($key)||!preg_match('/^[a-zA-Z0-9:_.-]{1,140}$/D',$key))throw new DomainException('Identificativo evento non valido.',422);return $key; }
function rpg_receipt(string $kind,int $id,string $key,string $type):?array { $row=ConnectDB()->query('SELECT * FROM rpg_ledger WHERE owner_kind=? AND owner_id=? AND event_key=?',[$kind,$id,$key])[0]??null;if($row&&$row['entry_type']!==$type)throw new DomainException('Identificativo già usato per un’altra operazione.',409);return $row; }
function rpg_ledger(string $kind,int $id,string $key,string $type,int $amount,string $reason,array $payload,int $actor):void { $p=rpg_progress($kind,$id);ConnectDB()->execute('INSERT INTO rpg_ledger(owner_kind,owner_id,event_key,entry_type,amount,xp_total,xp_spent,reason,payload,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$kind,$id,$key,$type,$amount,$p['xp_total'],$p['xp_spent'],$reason,rpg_json($payload),$actor,time()]); }

function rpg_claim_initial(string $kind,int $id,string $request,int $actor,?array $allocation=null):array {if($allocation===null)throw new DomainException('Scegli personalmente la distribuzione dei punti e conferma la creazione dalla scheda.',422);return rpg_complete_creation($kind,$id,$allocation,[],$request,$actor);}

function rpg_increase_stat(string $kind,int $id,string $stat,int $points,string $request,int $actor):array { $kind=rpg_kind($kind);if(!in_array($stat,RPG_STATS,true))throw new DomainException('Caratteristica non valida.',422);rpg_int($points,1,100,'Punti');$request=rpg_request_key($request);return rpg_atomic(function()use($kind,$id,$stat,$points,$request,$actor){$identity=rpg_identity($kind,$id,true);$p=rpg_progress($kind,$id,true);$receipt=rpg_receipt($kind,$id,$request,'stat');if($receipt){$payload=rpg_decode($receipt['payload']);if(($payload['stat']??'')!==$stat||($payload['points']??0)!==$points)throw new DomainException('La ricevuta appartiene a un altro incremento.',409);return rpg_sheet($kind,$id);}if(!rpg_race($identity['race_id'])['enabled'])throw new DomainException('Progressione razziale sospesa.',409);$values=rpg_stat_values($identity,$p);$forms=rpg_stat_forms($identity,$p);if($points>rpg_stat_training_room($forms,$stat))throw new DomainException('La caratteristica non può superare 100 in nessuna delle forme del personaggio.',422);if($p['xp_total']-$p['xp_spent']<$points)throw new DomainException('Esperienza disponibile insufficiente.',422);$trained=rpg_decode($p['trained_stats']);$trained[$stat]=(int)($trained[$stat]??0)+$points;ConnectDB()->execute('UPDATE rpg_progress SET trained_stats=?,xp_spent=xp_spent+?,xp_stats=xp_stats+?,version=version+1 WHERE owner_kind=? AND owner_id=?',[rpg_json($trained),$points,$points,$kind,$id]);rpg_ledger($kind,$id,$request,'stat',-$points,'Allenamento: '.rpg_stat_name($stat).'.',['stat'=>$stat,'points'=>$points,'before'=>$values[$stat],'after'=>$values[$stat]+$points,'forms'=>array_map(static fn($f)=>['race_id'=>$f['race_id'],'name'=>$f['name'],'before'=>$f['stats'][$stat],'after'=>$f['stats'][$stat]+$points],$forms)],$actor);return rpg_sheet($kind,$id);}); }
function rpg_buy_ability(string $kind,int $id,int $ability,string $request,int $actor):array { $kind=rpg_kind($kind);$request=rpg_request_key($request);return rpg_atomic(function()use($kind,$id,$ability,$request,$actor){rpg_identity($kind,$id,true);$p=rpg_progress($kind,$id,true);$receipt=rpg_receipt($kind,$id,$request,'ability');if($receipt){if((int)(rpg_decode($receipt['payload'])['ability_id']??0)!==$ability)throw new DomainException('La ricevuta appartiene a un’altra abilità.',409);return rpg_sheet($kind,$id);}$s=rpg_sheet($kind,$id,false);$found=null;foreach($s['abilities'] as $a)if($a['id']===$ability)$found=$a;if(!$found||!$found['available'])throw new DomainException($found['reason']??'Abilità non disponibile per questa razza.',422);if($found['owned']||!$found['learnable'])throw new DomainException('Abilità già posseduta o assegnata automaticamente alla razza.',409);ConnectDB()->execute('INSERT INTO rpg_learned(owner_kind,owner_id,ability_id,cost,learned_at) VALUES(?,?,?,?,?)',[$kind,$id,$ability,$found['cost'],time()]);ConnectDB()->execute('UPDATE rpg_progress SET xp_spent=xp_spent+?,xp_abilities=xp_abilities+?,version=version+1 WHERE owner_kind=? AND owner_id=?',[$found['cost'],$found['cost'],$kind,$id]);rpg_ledger($kind,$id,$request,'ability',-$found['cost'],'Appresa: '.$found['name'].'.',['ability_id'=>$ability,'name'=>$found['name']],$actor);return rpg_sheet($kind,$id);}); }
/** Trusted server capability; never expose a player-authored grant or model-generated amount. */
function rpg_grant_xp(string $kind,int $id,int $amount,string $reason,string $eventKey,int $actorId=0):array { $kind=rpg_kind($kind);rpg_int($amount,1,1000000,'Esperienza');$reason=rpg_text($reason,500,true);$eventKey=rpg_event_key($eventKey);return rpg_atomic(function()use($kind,$id,$amount,$reason,$eventKey,$actorId){rpg_identity($kind,$id,true);$p=rpg_progress($kind,$id,true);$receipt=rpg_receipt($kind,$id,$eventKey,'grant');if($receipt){if((int)$receipt['amount']!==$amount)throw new DomainException('Ricompensa già registrata con un valore diverso.',409);return ['total'=>$p['xp_total'],'spent'=>$p['xp_spent'],'available'=>$p['xp_total']-$p['xp_spent'],'replayed'=>true];}if($p['xp_total']+$amount>1000000000)throw new DomainException('Limite esperienza raggiunto.',422);ConnectDB()->execute('UPDATE rpg_progress SET xp_total=xp_total+?,version=version+1 WHERE owner_kind=? AND owner_id=?',[$amount,$kind,$id]);rpg_ledger($kind,$id,$eventKey,'grant',$amount,$reason,[],$actorId);return ['total'=>$p['xp_total']+$amount,'spent'=>$p['xp_spent'],'available'=>$p['xp_total']+$amount-$p['xp_spent'],'replayed'=>false];}); }
/** Reserve a declared ability atomically. Effects remain a proposal until the verdict engine applies them. */
function rpg_use_ability(string $kind,int $id,int $ability,array $context):array { $kind=rpg_kind($kind);$key=rpg_event_key($context['event_key']??'');$session=rpg_int($context['session_id']??0,0,PHP_INT_MAX,'Sessione');$round=rpg_int($context['round']??0,0,1000000,'Giro');return rpg_atomic(function()use($kind,$id,$ability,$key,$session,$round){rpg_identity($kind,$id,true);rpg_progress($kind,$id,true);$db=ConnectDB();$old=$db->query('SELECT * FROM rpg_ability_uses WHERE owner_kind=? AND owner_id=? AND event_key=?',[$kind,$id,$key])[0]??null;if($old){if((int)$old['ability_id']!==$ability||(int)$old['session_id']!==$session||(int)$old['round_number']!==$round)throw new DomainException('Dichiarazione abilità già registrata.',409);return rpg_decode($old['snapshot']);}$sheet=rpg_sheet($kind,$id,false);$a=null;foreach($sheet['abilities'] as $entry)if($entry['id']===$ability)$a=$entry;if(!$a||!$a['owned']||!$a['usable'])throw new DomainException($a['reason']??'Abilità non posseduta.',422);if(isset($a['rules'])&&$a['rules']['number']>=51)throw new DomainException('Questa resistenza si applica automaticamente quando ricevi un comando vampirico valido.',422);if(in_array($sheet['identity']['race_id'],[4,7],true)&&!in_array($a['effect']['type'],['narrative','perception','passive'],true))throw new DomainException('Una forma incorporea non può usare abilità fisiche.',422);
 $last=$db->query('SELECT round_number,created_at FROM rpg_ability_uses WHERE owner_kind=? AND owner_id=? AND ability_id=? AND session_id=? ORDER BY id DESC LIMIT 1',[$kind,$id,$ability,$session])[0]??null;if($last&&$a['cooldown']>0){$wait=$session>0?(int)$last['round_number']+$a['cooldown']+(isset($a['rules'])?1:0)-$round:0;if(($session>0&&$wait>0)||($session===0&&time()<(int)$last['created_at']+$a['cooldown']*60))throw new DomainException($session>0?'Abilità in recupero: attendi ancora '.$wait.' giri.':'Abilità in recupero: attendi qualche minuto.',409);}
 $snapshot=['owner_kind'=>$kind,'owner_id'=>$id,'id'=>$ability,'key'=>$a['key'],'name'=>$a['name'],'category'=>$a['category'],'description'=>$a['description'],'image'=>$a['image']??'','effect'=>$a['effect'],'stat'=>$a['effect']['stat'],'cooldown'=>$a['cooldown'],'session_id'=>$session,'round'=>$round,'source'=>$key,'version'=>$sheet['version'],'lineage_policy'=>rpg_lineage_policy()['version'],'access'=>$a['access'],'native_race_id'=>rpg_lineage_id($sheet['identity']),'form_race_id'=>$sheet['identity']['race_id']];if(isset($a['rules'])){$snapshot['human_rules']=$a['rules'];$snapshot['activation_roll']=random_int(1,100);$physical=in_array($a['effect']['stat'],['strength','dexterity','constitution'],true);$penalty=$sheet['malus'][$physical?'physical':'mental']['penalty'];$snapshot['activation_chance']=max(5,min(95,$a['rules']['probability']-$penalty));$snapshot['activated']=$snapshot['activation_roll']<=$snapshot['activation_chance'];}
 $db->execute('INSERT INTO rpg_ability_uses(owner_kind,owner_id,ability_id,event_key,session_id,round_number,snapshot,created_at) VALUES(?,?,?,?,?,?,?,?)',[$kind,$id,$ability,$key,$session,$round,rpg_json($snapshot),time()]);return $snapshot;}); }
function rpg_get_ability(string $kind,int $id,int $ability):array { $sheet=rpg_sheet($kind,$id,false);foreach($sheet['abilities'] as $a)if($a['id']===$ability){if(!$a['owned']||!$a['usable'])throw new DomainException($a['reason']?:'Abilità non posseduta.',422);return $a;}throw new DomainException('Abilità non disponibile nella forma attuale.',422); }
function rpg_admin_audit(int $actor,string $action,string $target,mixed $before,mixed $after):void { ConnectDB()->execute('INSERT INTO rpg_admin_audit(actor_id,action,target_id,before_state,after_state,created_at) VALUES(?,?,?,?,?,?)',[$actor,$action,$target,rpg_json($before),rpg_json($after),time()]); }
function rpg_admin_save_race(array $in,int $actor):array {
 $id=rpg_int($in['id']??0,0,100000,'Razza');$name=rpg_text($in['name']??'',30,true);$stats=$in['stats']??null;if(!is_array($stats)||array_diff(array_keys($stats),RPG_STATS)||count($stats)!==count(RPG_STATS))throw new DomainException('Inserisci tutte e otto le caratteristiche.',422);foreach($stats as $k=>$v)$stats[$k]=rpg_int($v,0,100,rpg_stat_name($k));
 $description=rpg_text($in['description']??'',1500);$source=rpg_text($in['source']??'',500);$special=rpg_bool($in['special']??false);$enabled=rpg_bool($in['enabled']??true);$extra=[];$alternate=$in['transformation_stats']??null;if($alternate!==null&&(!is_array($alternate)||count($alternate)!==8||array_diff(array_keys($alternate),RPG_STATS)))throw new DomainException('Inserisci le otto statistiche della forma alternativa.',422);foreach($alternate??[] as $k=>$v)$alternate[$k]=rpg_int($v,0,100,$k);
