 return rpg_atomic(function()use($id,$name,$stats,$description,$source,$special,$enabled,$extra,$alternate,$actor){
  $db=ConnectDB();if($id===0){$db->execute('INSERT INTO razze(nome,forza) VALUES(?,?)',[$name,$stats['strength']]);$id=(int)$db->lastInsertId();}$ready=alphano_transformation_ready();$languageReady=alphano_race_language_ready();if(array_key_exists('loses_human_language',$extra)&&!$languageReady)throw new DomainException('Aggiorna prima la configurazione del linguaggio razziale.',409);if(array_diff_key($extra,['loses_human_language'=>true])&&!$ready)throw new DomainException('Aggiorna prima la configurazione delle trasformazioni.',409);
  if($ready)$db->query("SELECT setting_key FROM rpg_settings WHERE setting_key='race_configuration_lock' FOR UPDATE");
  $fields=($ready?',c.human_default,c.transformation_enabled,c.transformation_human_text,c.transformation_special_text,c.transformation_stats':'').($languageReady?',c.loses_human_language':'');
  $before=$db->query('SELECT r.*,c.base_stats,c.description,c.source,c.special,c.enabled'.$fields.' FROM razze r LEFT JOIN rpg_races c ON c.race_id=r.id WHERE r.id=? FOR UPDATE',[$id])[0]??null;
  if(!$before)throw new DomainException('Razza non trovata.',404);
  $transform=array_replace(['human_default'=>false,'transformation_enabled'=>false,'transformation_human_text'=>'','transformation_special_text'=>'','loses_human_language'=>false],array_filter(array_intersect_key($before,array_flip(['human_default','transformation_enabled','transformation_human_text','transformation_special_text','loses_human_language'])),static fn($v)=>$v!==null),$extra);
  if(!empty($transform['human_default'])&&($special||!$enabled))throw new DomainException('La razza iniziale deve essere ordinaria e attiva.',422);
  $db->execute('UPDATE razze SET nome=?,forza=? WHERE id=?',[$name,$stats['strength'],$id]);
  $db->execute('INSERT INTO rpg_races(race_id,base_stats,description,source,special,enabled,updated_at) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE base_stats=VALUES(base_stats),description=VALUES(description),source=VALUES(source),special=VALUES(special),enabled=VALUES(enabled),updated_at=VALUES(updated_at)',[$id,rpg_json($stats),$description,$source,(int)$special,(int)$enabled,time()]);
  if($ready){if(!empty($transform['human_default']))$db->execute('UPDATE rpg_races SET human_default=0 WHERE race_id<>?',[$id]);$db->execute('UPDATE rpg_races SET human_default=?,transformation_enabled=?,transformation_human_text=?,transformation_special_text=? WHERE race_id=?',[(int)$transform['human_default'],(int)$transform['transformation_enabled'],$transform['transformation_human_text'],$transform['transformation_special_text'],$id]);alphano_human_race_id(true);alphano_transformation_config($id,true);}
  if($alternate!==null)$db->execute('UPDATE rpg_races SET transformation_stats=? WHERE race_id=?',[rpg_json($alternate),$id]);
  if($languageReady){$db->execute('UPDATE rpg_races SET loses_human_language=? WHERE race_id=?',[(int)$transform['loses_human_language'],$id]);alphano_race_loses_human_language($id,true);}
  rpg_admin_audit($actor,'save_race',(string)$id,$before,compact('name','stats','description','source','special','enabled','transform'));rpg_catalog(true);return rpg_race($id);
 });
}
function rpg_admin_save_stat(array $in,int $actor):array { $key=rpg_text($in['key']??'',32,true);if(!in_array($key,RPG_STATS,true))throw new DomainException('Caratteristica non riconosciuta.',422);$name=rpg_text($in['name']??'',80,true);$description=rpg_text($in['description']??'',500);$icon=rpg_text($in['icon']??'',160,true);if(!preg_match('~^(?:stat-(?:strength|dexterity|constitution|intelligence|wisdom|charisma|perception|willpower)|/uploads/statistics/[a-z0-9_-]+\.(?:svg|png|webp))$~D',$icon))throw new DomainException('Icona non disponibile: scegli un’icona centrale RPG.',422);return rpg_atomic(function()use($key,$name,$description,$icon,$actor){$before=ConnectDB()->query('SELECT * FROM rpg_characteristics WHERE stat_key=? FOR UPDATE',[$key])[0]??null;if(!$before)throw new DomainException('Caratteristica non trovata.',404);ConnectDB()->execute('UPDATE rpg_characteristics SET name=?,description=?,icon=? WHERE stat_key=?',[$name,$description,$icon,$key]);rpg_admin_audit($actor,'save_stat',$key,$before,compact('name','description','icon'));rpg_catalog(true);return compact('key','name','description','icon');}); }
function rpg_validate_requirements(mixed $in,int $id=0):array {
 if(!is_array($in)||array_diff(array_keys($in),['stats','abilities','sentient']))throw new DomainException('Requisiti non validi.',422);$stats=$in['stats']??[];if(!is_array($stats)||array_diff(array_keys($stats),RPG_STATS))throw new DomainException('Requisiti delle caratteristiche non validi.',422);foreach($stats as $k=>$v)$stats[$k]=rpg_int($v,0,100,rpg_stat_name($k));
 $abilities=$in['abilities']??[];if(!is_array($abilities)||!array_is_list($abilities)||count($abilities)>12)throw new DomainException('Prerequisiti abilità non validi.',422);$abilities=array_values(array_unique(array_map(static fn($v)=>rpg_int($v,1,PHP_INT_MAX,'Abilità richiesta'),$abilities)));$all=[];foreach(rpg_catalog()['abilities'] as $a)$all[$a['id']]=$a['requirements']['abilities']??[];foreach($abilities as $required)if(!isset($all[$required])||$required===$id)throw new DomainException('Abilità richiesta inesistente o autoreferenziale.',422);if($id){$all[$id]=$abilities;$walk=function(int $node,array $path)use(&$walk,$all){if(isset($path[$node]))throw new DomainException('I prerequisiti formano un ciclo.',422);$path[$node]=true;foreach($all[$node]??[] as $next)$walk((int)$next,$path);};$walk($id,[]);}
 $sentient=$in['sentient']??null;if($sentient!==null)$sentient=rpg_bool($sentient);return ['stats'=>$stats,'abilities'=>$abilities,'sentient'=>$sentient];
}
function rpg_validate_effect(mixed $in,string $kind):array {
 $defaults=['type'=>$kind,'stat'=>'strength','bonus'=>0,'damage'=>0,'heal'=>0,'duration'=>0,'target'=>in_array($kind,['heal','defence'],true)?'self':'enemy','requires_weapon'=>false,'recognizes_disguise'=>false];if(!is_array($in)||array_diff(array_keys($in),array_keys($defaults)))throw new DomainException('Effetto non valido.',422);$e=array_replace($defaults,$in);if($e['type']!==$kind||!in_array($kind,RPG_EFFECT_TYPES,true)||!in_array($e['stat'],RPG_STATS,true)||!in_array($e['target'],['self','enemy'],true))throw new DomainException('Tipo, caratteristica o bersaglio dell’effetto non valido.',422);foreach(['bonus'=>30,'damage'=>100,'heal'=>150,'duration'=>5] as $k=>$max)$e[$k]=rpg_int($e[$k],0,$max,'Effetto '.$k);$e['requires_weapon']=rpg_bool($e['requires_weapon']);$e['recognizes_disguise']=rpg_bool($e['recognizes_disguise']);if($e['recognizes_disguise']&&$kind!=='passive')throw new DomainException('Il riconoscimento dei travestimenti richiede un’abilità passiva.',422);if(!$e['recognizes_disguise'])unset($e['recognizes_disguise']);if(($e['heal']>0&&$kind!=='heal')||($kind==='heal'&&($e['target']!=='self'||$e['damage']>0))||($e['damage']>0&&!in_array($kind,['attack','mental'],true))||($e['duration']>0&&$kind!=='mental'))throw new DomainException('Conseguenze incompatibili con il tipo di abilità.',422);return $e;
