function rpg_admin_save_ability(array $in,int $actor):array {
 $id=rpg_int($in['id']??0,0,PHP_INT_MAX,'Abilità');$key=rpg_text($in['key']??'',80,true);if(str_starts_with($key,'org_'))throw new DomainException('Le discipline organizzative si modificano con una nuova revisione in Accademia.',422);if(!preg_match('/^[a-z][a-z0-9_]{2,79}$/D',$key))throw new DomainException('Codice abilità non valido.',422);$name=rpg_text($in['name']??'',100,true);$description=rpg_text($in['description']??'',2000,true);$source=rpg_text($in['source']??'',500);$image=array_key_exists('image',$in)?rpg_ability_image($in['image']):null;$category=$in['category']??(empty($in['innate'])?'purchasable':'innate');if(!in_array($category,['innate','special','purchasable'],true))throw new DomainException('Categoria abilità non valida.',422);$kind=$in['kind']??'';if(!in_array($kind,RPG_EFFECT_TYPES,true))throw new DomainException('Tipo di abilità non valido.',422);
 $races=$in['race_ids']??[];if(!is_array($races)||!array_is_list($races)||!$races||count($races)>100)throw new DomainException('Seleziona almeno una razza.',422);$races=array_values(array_unique(array_map(static fn($v)=>rpg_int($v,1,100000,'Razza'),$races)));foreach($races as $rid)rpg_race($rid);
 $requirements=rpg_validate_requirements($in['requirements']??[],$id);rpg_validate_lineage_assignment($key,$races);$cost=rpg_ability_learnable(['category'=>$category,'key'=>$key])?rpg_int($in['cost']??0,1,1000000,'Costo esperienza'):0;$cooldown=rpg_int($in['cooldown']??0,0,100,'Recupero');$effect=rpg_validate_effect($in['effect']??[],$kind);if(rpg_human_rule($key)){$effect['human_v2']=true;$effect['manual_rules']=rpg_validate_human_rule_overrides($in['human_rules']??[]);}$enabled=rpg_bool($in['enabled']??true);if(array_intersect($races,[4,7])&&!in_array($kind,['narrative','perception','passive'],true))throw new DomainException('Spiriti e vampiri caduti non possono ricevere poteri fisici.',422);
 return rpg_atomic(function()use($id,$key,$name,$description,$source,$image,$category,$kind,$races,$requirements,$cost,$cooldown,$effect,$enabled,$actor){$db=ConnectDB();$db->query("SELECT setting_key FROM rpg_settings WHERE setting_key='quest_xp_enabled' FOR UPDATE");rpg_catalog(true);$requirements=rpg_validate_requirements($requirements,$id);$before=$id?($db->query('SELECT * FROM rpg_abilities WHERE id=? FOR UPDATE',[$id])[0]??null):null;if($id&&!$before)throw new DomainException('Abilità non trovata.',404);if($before&&$before['ability_key']!==$key)throw new DomainException('Il codice identifica l’origine della capacità e non può cambiare; modifica nome, effetti e requisiti.',422);$other=$db->query('SELECT id FROM rpg_abilities WHERE ability_key=? AND id<>?',[$key,$id]);if($other)throw new DomainException('Codice già utilizzato da un’altra abilità.',409);$values=[$key,$name,$description,$source,$category,$kind,rpg_json($races),rpg_json($requirements),$cost,$cooldown,rpg_json($effect),(int)$enabled,time()];if($id)$db->execute('UPDATE rpg_abilities SET ability_key=?,name=?,description=?,source=?,category=?,kind=?,race_ids=?,requirements=?,cost=?,cooldown=?,effect=?,enabled=?,updated_at=? WHERE id=?',[...$values,$id]);else{$db->execute('INSERT INTO rpg_abilities(ability_key,name,description,source,category,kind,race_ids,requirements,cost,cooldown,effect,enabled,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',$values);$id=(int)$db->lastInsertId();}$image??=(string)($before['image']??'');$db->execute('UPDATE rpg_abilities SET image=? WHERE id=?',[$image,$id]);rpg_admin_audit($actor,'save_ability',(string)$id,$before,compact('key','name','description','source','image','category','kind','races','requirements','cost','cooldown','effect','enabled'));rpg_catalog(true);foreach(rpg_catalog()['abilities'] as $a)if($a['id']===$id)return $a;throw new LogicException('Abilità non disponibile dopo il salvataggio.');});
