function rpg_validate_settings_combination(array $combined):void {
 foreach([['attack_strength','attack_dexterity','attack_perception'],['defence_dexterity','defence_constitution','defence_willpower'],['mental_charisma','mental_intelligence','mental_willpower'],['resist_willpower','resist_wisdom']] as $group)if(array_sum(array_intersect_key($combined,array_flip($group)))!==100)throw new DomainException('La somma dei pesi di ogni prova deve essere 100.',422);
