function rpg_admin_save_settings(mixed $in,int $actor):array {
 if(!is_array($in))throw new DomainException('Impostazioni non valide.',422);$schema=array_column(rpg_settings_schema(),null,'key');if(array_diff(array_keys($in),array_keys($schema)))throw new DomainException('Impostazione non modificabile.',422);$values=[];foreach($in as $k=>$v)$values[$k]=rpg_int($v,$schema[$k]['min'],$schema[$k]['max'],$schema[$k]['name']);
 return rpg_atomic(function()use($values,$actor){$db=ConnectDB();$db->query("SELECT setting_key FROM rpg_settings WHERE setting_key='quest_xp_enabled' FOR UPDATE");$before=rpg_settings(true);rpg_validate_settings_combination(array_replace($before,$values));foreach($values as $k=>$v)$db->execute('UPDATE rpg_settings SET value=? WHERE setting_key=?',[$v,$k]);rpg_admin_audit($actor,'save_settings','combat',$before,rpg_settings(true));return rpg_settings();});
}
function rpg_admin_data():array { $cat=rpg_catalog();$players=ConnectDB()->query('SELECT id,nome AS name,razza AS race_id FROM utenti ORDER BY nome LIMIT 500');foreach($players as &$p){$p['id']=(int)$p['id'];$p['race_id']=(int)$p['race_id'];}return $cat+['settings'=>rpg_settings(),'settings_schema'=>rpg_settings_schema(),'effects'=>RPG_EFFECT_TYPES,'players'=>$players,'npcs'=>ConnectDB()->query('SELECT id,name FROM ai_npcs ORDER BY name'),'history'=>['items'=>ConnectDB()->query('SELECT l.id,l.owner_kind,l.owner_id,l.entry_type AS type,l.amount,l.reason,l.created_at,l.actor_id,actor.nome AS actor_name,CASE WHEN l.owner_kind=\'pg\' THEN u.nome ELSE n.name END AS name FROM rpg_ledger l LEFT JOIN utenti actor ON actor.id=l.actor_id LEFT JOIN utenti u ON l.owner_kind=\'pg\' AND u.id=l.owner_id LEFT JOIN ai_npcs n ON l.owner_kind=\'npc\' AND n.id=l.owner_id ORDER BY l.id DESC LIMIT 50')]]; }
